
import { defineComponent, shallowRef, computed } from 'vue'
import { VIcon } from '@/ui'

export default defineComponent({
  name: 'CollapsibleContainer',
  components: {
    VIcon,
  },
  props: {
    /** 标题栏文本，在不重写slot的情况下修改显示文本 */
    title: {
      type: String,
      default: '',
    },

    /** 当前展开状态 */
    expanded: {
      type: Boolean,
      default: undefined,
    },

    /** 初始展开状态 */
    defaultExpanded: {
      type: Boolean,
      default: false,
    },

    /**
     * 点击标题栏任意位置是否能触发展开/收起操作
     *
     * 通常在重写了title slot，有自定义的点击事件的情况禁用
     */
    enableExpandByHeader: {
      type: Boolean,
      default: true,
    },

    /** 隐藏展开按钮 */
    hideExpandButton: {
      type: Boolean,
      default: false,
    },

    /** 禁用内容区域 */
    disableContent: {
      type: Boolean,
      default: false,
    },
  },
  emits: ['expanded'],
  setup(props, { emit }) {
    // 定义内部值以便在未传递参数时能正常工作
    const internalExpanded = shallowRef(props.defaultExpanded)
    const computedExpanded = computed(() =>
      props.expanded !== undefined ? props.expanded : internalExpanded.value,
    )

    // 切换展开/收起状态
    const toggleExpand = () => {
      if (props.expanded !== undefined) {
        emit('expanded', !props.expanded)
      } else {
        internalExpanded.value = !internalExpanded.value
      }
    }

    const onHeaderClick = () => {
      if (props.enableExpandByHeader) {
        toggleExpand()
      }
    }

    const onBtnClick = (e: MouseEvent) => {
      // 避免重复触发点击事件
      e.stopPropagation()

      toggleExpand()
    }

    return {
      computedExpanded,
      onBtnClick,
      onHeaderClick,
    }
  },
})
