
export default Vue.extend({
  props: {
    tags: {
      type: Array,
      required: true,
    },
    size: {
      type: Number,
      default: 18,
    },
    stroke: {
      type: Number,
      default: 3,
    },
  },
  data() {
    const radius = this.size / 2 - this.stroke
    const circumference = radius * 2 * Math.PI

    return {
      radius,
      circumference,
    }
  },
  methods: {
    getStyle(tag: { color: string }, index: number) {
      const strokeDashoffset = (index / this.tags.length) * this.circumference
      return {
        strokeDashoffset,
        stroke: tag.color,
      }
    },
  },
})
