
import { defineComponent } from 'vue'
import { fetchRecommendations, getRecommendationAccount, RecommendedVideo } from './recommendations'
import { mountNativePlayer, NativePlayerState } from './native-player'

const blockedKey = (accountId: string) => `bilibiliClear.shorts.blockedAuthors.${accountId}`
const readBlocked = (accountId: string): string[] => {
  const saved = GM_getValue(blockedKey(accountId), [])
  return Array.isArray(saved)
    ? saved.filter(id => typeof id === 'string' && /^\d+$/.test(id)).slice(-500)
    : []
}
const initialPlayerState = (): NativePlayerState => ({
  ready: false,
  playing: false,
  muted: false,
  needsGesture: false,
  error: '',
})
type NativePlayer = ReturnType<typeof mountNativePlayer>
interface PlayerSlot {
  key: number
  revision: number
  video: RecommendedVideo | null
  state: NativePlayerState
  presented: boolean
}
const initialPlayerSlots = (): PlayerSlot[] =>
  [1, 2].map(key => ({
    key,
    revision: 0,
    video: null,
    state: initialPlayerState(),
    presented: false,
  }))
const queueLowWater = 4
const queueTarget = 10
const coverWaitLimit = 3000

export default defineComponent({
  name: 'ClearShortsView',
  props: { accountId: { type: String, default: getRecommendationAccount } },
  data() {
    return {
      videos: [] as RecommendedVideo[],
      activeIndex: 0,
      nextPage: 1,
      loading: false,
      navigating: false,
      boundaryBvid: '',
      error: '',
      disposed: false,
      navigationRevision: 0,
      accountChanged: false,
      suspended: false,
      request: null as AbortController | null,
      loadTask: null as Promise<void> | null,
      seen: new Set<string>(),
      blockedAuthors: readBlocked(this.accountId),
      lastHidden: null as RecommendedVideo | null,
      player: null as NativePlayer | null,
      playerState: initialPlayerState(),
      playerSlots: initialPlayerSlots(),
      slotPlayers: new Map<number, NativePlayer>(),
      playerEpoch: 0,
      activePlayerKey: 0,
      coverPreloads: new Map<string, HTMLImageElement>(),
      coverVisible: false,
      coverTimer: undefined as number | undefined,
      wheelDelta: 0,
      lastNavigation: 0,
      touchStartY: null as number | null,
    }
  },
  computed: {
    current(): RecommendedVideo | undefined {
      return this.videos[this.activeIndex]
    },
    currentBvid(): string {
      return this.current?.bvid || ''
    },
    currentPresented(): boolean {
      return this.playerSlots.some(slot => slot.video?.bvid === this.currentBvid && slot.presented)
    },
    videoUrl(): string {
      return this.current ? `https://www.bilibili.com/video/${this.current.bvid}/` : ''
    },
    commentUrl(): string {
      return this.videoUrl ? `${this.videoUrl}#comment` : ''
    },
    authorUrl(): string {
      return this.current ? `https://space.bilibili.com/${this.current.authorId}` : ''
    },
  },
  watch: {
    currentBvid() {
      this.startCoverWait()
      this.syncPlayerSlots()
      this.maybePrefetch()
    },
    accountId() {
      this.cancelLoading()
      this.disposePlayers()
      this.videos = []
      this.lastHidden = null
      this.accountChanged = true
      this.error = '登录账号已变化，请关闭竖屏模式后重新打开。'
    },
  },
  mounted() {
    this.focusFirst()
    document.addEventListener('focusin', this.containFocus)
    document.addEventListener('visibilitychange', this.onVisibility)
    window.addEventListener('focus', this.checkAccount)
    this.loadMore()
  },
  beforeDestroy() {
    this.disposed = true
    this.cancelLoading()
    this.disposePlayers()
    document.removeEventListener('focusin', this.containFocus)
    document.removeEventListener('visibilitychange', this.onVisibility)
    window.removeEventListener('focus', this.checkAccount)
  },
  methods: {
    durationText(value: number) {
      const seconds = Math.max(0, Math.floor(value))
      return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`
    },
    cancelLoading() {
      this.cancelNavigation()
      this.request?.abort()
      this.request = null
      this.loading = false
      this.loadTask = null
    },
    cancelNavigation() {
      this.navigationRevision++
      this.navigating = false
      this.boundaryBvid = ''
    },
    stopCoverWait() {
      window.clearTimeout(this.coverTimer)
      this.coverTimer = undefined
      this.coverVisible = false
    },
    startCoverWait() {
      this.stopCoverWait()
      if (!this.current || this.disposed || document.hidden) {
        return
      }
      const bvid = this.currentBvid
      this.coverVisible = true
      // Never cover native login, entitlement, buffering or retry controls forever.
      this.coverTimer = window.setTimeout(() => {
        if (!this.disposed && this.currentBvid === bvid) {
          this.stopCoverWait()
        }
      }, coverWaitLimit)
    },
    disposeSlot(slot: PlayerSlot) {
      slot.revision++
      this.slotPlayers.get(slot.key)?.dispose()
      this.slotPlayers.delete(slot.key)
      if (this.activePlayerKey === slot.key) {
        this.player = null
        this.activePlayerKey = 0
      }
      slot.video = null
      slot.state = initialPlayerState()
      slot.presented = false
    },
    clearCoverPreloads() {
      this.coverPreloads.forEach(image => {
        image.src = ''
      })
      this.coverPreloads.clear()
    },
    disposePlayers() {
      this.playerEpoch++
      this.playerSlots.forEach(this.disposeSlot)
      this.player = null
      this.activePlayerKey = 0
      this.clearCoverPreloads()
      this.stopCoverWait()
    },
    warmCovers() {
      if (document.hidden || this.disposed) {
        this.clearCoverPreloads()
        return
      }
      const upcoming = this.videos.slice(this.activeIndex + 1, this.activeIndex + 4)
      const retained = new Set(upcoming.map(video => video.bvid))
      this.coverPreloads.forEach((image, bvid) => {
        if (!retained.has(bvid)) {
          image.src = ''
          this.coverPreloads.delete(bvid)
        }
      })
      upcoming.forEach(video => {
        if (!video.cover || this.coverPreloads.has(video.bvid)) {
          return
        }
        const image = new Image()
        image.referrerPolicy = 'no-referrer'
        image.src = video.cover
        this.coverPreloads.set(video.bvid, image)
      })
    },
    async syncPlayerSlots() {
      const epoch = ++this.playerEpoch
      if (this.disposed || this.accountChanged || !this.current) {
        this.disposePlayers()
        this.playerState = initialPlayerState()
        return
      }
      // Keep both iframe nodes in fixed DOM positions. Moving the next frame before
      // the previous one can reload its browsing context, especially in Safari.
      const desired = this.videos.slice(
        this.activeIndex,
        this.activeIndex + (document.hidden ? 1 : 2),
      )
      const keep = new Set(desired.map(video => video.bvid))
      this.playerSlots
        .filter(slot => slot.video && !keep.has(slot.video.bvid))
        .forEach(this.disposeSlot)
      for (const video of desired) {
        if (!this.playerSlots.some(slot => slot.video?.bvid === video.bvid)) {
          const available = this.playerSlots.find(slot => !slot.video)
          if (available) {
            available.video = video
          }
        }
      }
      this.playerState = {
        ...(this.playerSlots.find(slot => slot.video?.bvid === this.currentBvid)?.state ||
          initialPlayerState()),
      }
      this.warmCovers()
      await this.$nextTick()
      if (this.disposed || epoch !== this.playerEpoch) {
        return
      }
      for (const slot of this.playerSlots) {
        const { video } = slot
        if (!video || this.slotPlayers.has(slot.key)) {
          continue
        }
        const ref = this.$refs[`player-${slot.key}`]
        const iframe = (Array.isArray(ref) ? ref[0] : ref) as HTMLIFrameElement | undefined
        if (!iframe) {
          continue
        }
        const active = video.bvid === this.currentBvid
        const { revision } = slot
        const ownsSlot = () => !this.disposed && slot.revision === revision && slot.video === video
        const controller = mountNativePlayer(iframe, {
          bvid: video.bvid,
          cid: video.cid,
          preload: !active || document.hidden,
          onState: state => {
            if (!ownsSlot()) {
              return
            }
            slot.state = { ...state }
            if (state.playing) {
              slot.presented = true
            }
            if (video.bvid === this.currentBvid) {
              this.playerState = { ...state }
              if (state.playing || state.error || state.needsGesture) {
                this.stopCoverWait()
              }
            }
          },
          onNavigate: direction => {
            if (ownsSlot() && video.bvid === this.currentBvid) {
              this.navigate(direction)
            }
          },
          onClose: () => {
            if (ownsSlot() && video.bvid === this.currentBvid) {
              this.$emit('close')
            }
          },
        })
        this.slotPlayers.set(slot.key, controller)
      }
      const activeSlot = this.playerSlots.find(slot => slot.video?.bvid === this.currentBvid)
      if (!activeSlot) {
        return
      }
      const nextPlayer = this.slotPlayers.get(activeSlot.key)
      if (nextPlayer && this.activePlayerKey !== activeSlot.key) {
        this.player?.pause()
        this.player = nextPlayer
        this.activePlayerKey = activeSlot.key
        this.suspended = document.hidden
        if (document.hidden) {
          nextPlayer.pause()
        } else {
          nextPlayer.play()
        }
      }
    },
    reloadPlayer() {
      this.cancelNavigation()
      const slot = this.playerSlots.find(item => item.video?.bvid === this.currentBvid)
      if (slot) {
        this.disposeSlot(slot)
      }
      this.startCoverWait()
      this.syncPlayerSlots()
    },
    checkAccount() {
      this.isCurrentAccount()
    },
    isCurrentAccount() {
      if (!this.accountChanged && this.accountId && this.accountId === getRecommendationAccount()) {
        return true
      }
      this.cancelLoading()
      this.disposePlayers()
      this.videos = []
      this.lastHidden = null
      this.accountChanged = true
      this.error = '请登录 B 站，并重新打开竖屏模式。'
      return false
    },
    maybePrefetch() {
      if (document.hidden || this.disposed || this.error || this.accountChanged) {
        return
      }
      if (this.videos.length - this.activeIndex - 1 <= queueLowWater) {
        this.loadMore()
      }
    },
    loadMore(): Promise<void> {
      // Navigation at the queue boundary waits for the same background fill, never a no-op.
      if (this.loadTask) {
        return this.loadTask
      }
      if (this.disposed || document.hidden || !this.isCurrentAccount()) {
        return Promise.resolve()
      }
      this.loading = true
      this.error = ''
      const request = new AbortController()
      this.request = request
      const task = this.fillQueue(request).finally(() => {
        if (this.request === request) {
          this.loading = false
          this.request = null
          this.loadTask = null
        }
      })
      this.loadTask = task
      return task
    },
    async fillQueue(request: AbortController) {
      let added = 0
      try {
        // Bounded work even when several recommendation pages contain only exclusions.
        for (let attempt = 0; attempt < 4; attempt += 1) {
          if (this.videos.length - this.activeIndex - 1 >= queueTarget) {
            break
          }
          const batch = await fetchRecommendations(this.nextPage, request.signal, {
            authors: new Set(this.blockedAuthors),
            videos: this.seen,
          })
          if (
            this.disposed ||
            request.signal.aborted ||
            this.request !== request ||
            !this.isCurrentAccount()
          ) {
            return
          }
          this.nextPage++
          const incoming = batch.items.filter(
            video => !this.seen.has(video.bvid) && !this.blockedAuthors.includes(video.authorId),
          )
          incoming.forEach(video => this.seen.add(video.bvid))
          this.videos.push(...incoming)
          added += incoming.length
          if (this.videos.length > 100 && this.activeIndex > 30) {
            const trim = Math.min(this.activeIndex - 30, this.videos.length - 100)
            this.videos.splice(0, trim)
            this.activeIndex -= trim
          }
          // A waiting swipe can use the first new result while the rest of the queue fills.
          if (
            this.navigating &&
            this.currentBvid === this.boundaryBvid &&
            this.activeIndex + 1 < this.videos.length
          ) {
            this.activeIndex++
            this.cancelNavigation()
          }
          this.syncPlayerSlots()
        }
        if (!added && this.videos.length - this.activeIndex - 1 <= queueLowWater) {
          this.error = '这几批推荐已被过滤或已经看过，可以稍后再换一批。'
        }
      } catch (error) {
        if (!this.disposed && !request.signal.aborted && this.request === request) {
          this.error = error instanceof Error ? error.message : '获取推荐失败，请稍后重试。'
        }
        request.abort()
      }
    },
    navigate(direction: -1 | 1) {
      if (Date.now() - this.lastNavigation < 650) {
        return
      }
      if (direction > 0) {
        this.next()
      } else {
        this.previous()
      }
    },
    async next() {
      if (this.navigating || !this.isCurrentAccount()) {
        return
      }
      const intent = ++this.navigationRevision
      this.lastNavigation = Date.now()
      if (this.activeIndex + 1 < this.videos.length) {
        this.activeIndex++
        return
      }
      this.navigating = true
      const previous = this.current?.bvid
      this.boundaryBvid = previous || ''
      try {
        await this.loadMore()
        if (
          !this.disposed &&
          intent === this.navigationRevision &&
          previous &&
          this.current?.bvid === previous &&
          this.activeIndex + 1 < this.videos.length
        ) {
          this.activeIndex++
        }
      } finally {
        if (intent === this.navigationRevision) {
          this.cancelNavigation()
        }
      }
    },
    previous() {
      if (this.activeIndex > 0 && this.isCurrentAccount()) {
        this.cancelNavigation()
        this.lastNavigation = Date.now()
        this.activeIndex--
      }
    },
    hideAuthor() {
      if (!this.current || !this.isCurrentAccount()) {
        return
      }
      this.cancelNavigation()
      const hidden = this.current
      const previousVideos = this.videos
        .slice(0, this.activeIndex)
        .filter(video => video.authorId !== hidden.authorId)
      this.lastHidden = hidden
      this.blockedAuthors = [...new Set([...this.blockedAuthors, hidden.authorId])].slice(-500)
      GM_setValue(blockedKey(this.accountId), this.blockedAuthors)
      this.videos = this.videos.filter(video => video.authorId !== hidden.authorId)
      this.activeIndex = Math.min(previousVideos.length, Math.max(0, this.videos.length - 1))
      this.syncPlayerSlots()
      this.maybePrefetch()
    },
    undoHide() {
      if (!this.lastHidden || !this.isCurrentAccount()) {
        return
      }
      this.cancelNavigation()
      this.blockedAuthors = this.blockedAuthors.filter(id => id !== this.lastHidden.authorId)
      GM_setValue(blockedKey(this.accountId), this.blockedAuthors)
      if (!this.videos.some(video => video.bvid === this.lastHidden.bvid)) {
        this.videos.splice(this.activeIndex, 0, this.lastHidden)
      }
      this.lastHidden = null
      this.syncPlayerSlots()
      this.maybePrefetch()
    },
    onWheel(event: WheelEvent) {
      if (
        event.ctrlKey ||
        Math.abs(event.deltaX) > Math.abs(event.deltaY) ||
        (event.target as HTMLElement)?.closest('.clear-shorts-help')
      ) {
        return
      }
      event.preventDefault()
      if (Date.now() - this.lastNavigation < 650) {
        return
      }
      this.wheelDelta += event.deltaY * (event.deltaMode === 1 ? 16 : 1)
      if (Math.abs(this.wheelDelta) < 80) {
        return
      }
      this.navigate(this.wheelDelta > 0 ? 1 : -1)
      this.wheelDelta = 0
    },
    onTouchStart(event: TouchEvent) {
      this.touchStartY =
        event.touches.length === 1 && !(event.target as HTMLElement)?.closest('.clear-shorts-help')
          ? event.touches[0].clientY
          : null
    },
    onTouchEnd(event: TouchEvent) {
      if (this.touchStartY === null || event.changedTouches.length !== 1) {
        return
      }
      const distance = this.touchStartY - event.changedTouches[0].clientY
      this.touchStartY = null
      if (Math.abs(distance) >= 70) {
        this.navigate(distance > 0 ? 1 : -1)
      }
    },
    onKeydown(event: KeyboardEvent) {
      if (event.key === 'Escape') {
        event.stopPropagation()
        this.$emit('close')
        return
      }
      const target = event.target as HTMLElement
      if (target?.closest('input, textarea, select, [contenteditable="true"]')) {
        return
      }
      if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
        event.preventDefault()
        event.stopPropagation()
        this.navigate(event.key === 'ArrowDown' ? 1 : -1)
      }
    },
    containFocus(event: FocusEvent) {
      const dialog = this.$refs.dialog as HTMLElement
      if (dialog && event.target instanceof Node && !dialog.contains(event.target)) {
        this.focusFirst()
      }
    },
    focusFirst() {
      ;(this.$refs.close as HTMLButtonElement)?.focus()
    },
    focusLast() {
      const elements = (this.$refs.dialog as HTMLElement)?.querySelectorAll<HTMLElement>(
        'button:not(:disabled), a[href], summary, iframe.is-active',
      )
      elements?.[elements.length - 1]?.focus()
    },
    onVisibility() {
      if (document.hidden) {
        this.cancelLoading()
        this.stopCoverWait()
        this.player?.pause()
        this.suspended = true
        this.syncPlayerSlots()
      } else if (this.isCurrentAccount()) {
        this.syncPlayerSlots()
        this.maybePrefetch()
      }
    },
    async resume() {
      if (!this.isCurrentAccount()) {
        return
      }
      this.suspended = false
      try {
        await this.player?.play()
      } catch {
        this.playerState = { ...this.playerState, needsGesture: true }
      }
    },
    toggleMute() {
      this.player?.toggleMute()
    },
  },
})
