
import { VIcon } from '@/ui'

export default Vue.extend({
  components: {
    VIcon,
  },
  props: {
    item: {
      type: Object,
      required: true,
    },
    component: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      disabled: false,
    }
  },
  methods: {
    async handleClick() {
      if (this.disabled) {
        return
      }
      try {
        this.disabled = true
        await this.item.action(this.component)
      } finally {
        this.disabled = false
      }
    },
  },
})
